import gzip, shutil
from pathlib import Path

problems = []
for row in rows:
    for key in ("r1", "r2"):
        path = Path(row[key]).resolve()
        if not path.exists() or path.stat().st_size == 0:
            problems.append(f"{key} 缺失或为空: {path}")
            continue
        with open(path, "rb") as fh:
            if fh.read(2) != b"\x1f\x8b":
                problems.append(f"{key} 不是 gzip（可能是下载失败的页面）: {path}")
if shutil.disk_usage(RES_DIR).free < MIN_FREE_BYTES:
    problems.append(f"剩余空间不足: {shutil.disk_usage(RES_DIR).free}")
if problems:
    raise SystemExit("输入校验失败：\n" + "\n".join(problems))

import hashlib

def sha256_of(path, chunk=8 << 20):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for block in iter(lambda: fh.read(chunk), b""):
            h.update(block)
    return h.hexdigest()

rows = []
for path in sorted(RAW_DIR.glob("*.fq.gz")):
    rows.append({"path": str(path.resolve()), "size": path.stat().st_size,
                 "sha256": sha256_of(path)})
pd.DataFrame(rows).to_csv(LOG_DIR / f"{project}.checksums.tsv", sep="\t", index=False)
